-- #121 체결 기반 시장 통계 (ADR-0107 결정 1 #177 11–15항, 결정 4 #121 행들; ADR-0116). From this
-- migration on the intake writes the market's statistics with each fill, in the fill's transaction
-- (@buddha/db market-stats.ts): `markets` gains the 시장가격's 갱신시각 (`last_fill_at`) and the
-- CHECK that pairs it with `last_price`, and the fills' market index takes the (market_id,
-- created_at, id) shape the price history is read by (the chart reads `fills` now; `price_ticks`
-- stays as it is, read and written by nothing). Generated by `drizzle-kit generate`, then
-- hand-edited where marked: this header and the guard. The snapshot matches the schema (a re-run
-- of `generate` reports no changes).
--
-- Not merge-wait class (2) (ADR-0107 결정 3): a nullable column, a CHECK every row passes and an
-- index swap; no row is changed or deleted and no release setting is added. The statistics start
-- from the first fill, so the guard below refuses a database that holds a fill or a market
-- statistic already rather than recount it (a recount is an UPDATE: an owner's question, see
-- docs/RESET.md). The deployed database has neither: 0060 wiped it, and `order.accepting` has
-- stayed closed since 0062.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.fills)
     OR EXISTS (SELECT 1 FROM public.markets
                WHERE last_price IS NOT NULL OR volume_coin <> 0 OR trade_count <> 0
                   OR trader_count <> 0) THEN
    RAISE EXCEPTION '0063 starts the market statistics from the first fill, so no fill and no statistic may exist yet: see docs/RESET.md';
  END IF;
END
$$;--> statement-breakpoint
DROP INDEX "fills_market_id_created_at_idx";--> statement-breakpoint
ALTER TABLE "markets" ADD COLUMN "last_fill_at" timestamp (3) with time zone;--> statement-breakpoint
CREATE INDEX "fills_market_id_created_at_id_idx" ON "fills" USING btree ("market_id","created_at","id");--> statement-breakpoint
ALTER TABLE "markets" ADD CONSTRAINT "markets_last_fill_at_check" CHECK (("markets"."last_price" IS NULL) = ("markets"."last_fill_at" IS NULL));